INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '2c5a98b1-90c4-4f88-a2b3-1c4f9b012a10'::uuid, 'landing-page-my-pham-tiktok-shop', 'Template Landing Page Mỹ Phẩm Chuẩn TikTok Shop', 'Mẫu landing page bán mỹ phẩm dưỡng da tối ưu mobile 375px, gắn giỏ hàng TikTok Shop & Shopee.', 'Gói template Next.js + HTML/CSS do nhóm tự thiết kế dành riêng cho shop mỹ phẩm 1–3 nhân sự. Tập trung trình bày bảng thành phần dịu nhẹ, chứng nhận công bố sản phẩm, CTA chốt đơn nhanh qua TikTok Shop/Shopee và tuân thủ chính sách quảng cáo không cam kết trị liệu.', 'template', 'Mỹ phẩm', 490000, '/products/landing-page-my-pham-tiktok-shop', NULL, 'original', 'Sản phẩm gốc do nhóm nghiên cứu tự thiết kế 100%, cấp quyền sử dụng thương mại cho 1 shop.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Shopee","Facebook"],"deliverables":["Source code template responsive 375px - 1440px","Bảng nội dung chuẩn chính sách mỹ phẩm không trị liệu","Khối hiển thị giấy công bố & hướng dẫn triển khai trong 30 phút"],"tech_stack":["HTML5","CSS3","Next.js"],"setup_time_minutes":30,"guide_summary":"Thay logo, bảng thành phần, giá bán và link sản phẩm TikTok Shop để chạy ngay."}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
