INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '7a9c11d2-54e3-4c99-8b10-0f2d3e4a5b6c'::uuid, 'prompt-pack-mo-ta-my-pham', 'Prompt Pack Mô Tả & Kịch Bản Video Mỹ Phẩm', '60 prompt AI viết mô tả sản phẩm dưỡng da, kịch bản TikTok 30s không vi phạm từ cấm.', 'Bộ 60 prompt tối ưu cho chủ shop mỹ phẩm viết mô tả chuẩn SEO Shopee/TikTok Shop, trả lời bình luận khách hỏi về loại da và dựng kịch bản video ngắn tránh các từ ngữ cam kết điều trị y khoa.', 'prompt_pack', 'Mỹ phẩm', 290000, NULL, NULL, 'original', 'Bộ prompt biên soạn gốc bởi nhóm nội dung, dùng không giới hạn cho các kênh của 1 shop.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Shopee","Facebook"],"deliverables":["60 prompt phân loại theo tình huống bán hàng mỹ phẩm","Checklist từ khóa bị hạn chế trên sàn TMĐT","Bộ khung kịch bản video ngắn 30 giây quay bằng điện thoại"],"tech_stack":["Notion","Markdown","PDF"],"setup_time_minutes":15,"guide_summary":"Điền tên sản phẩm, thành phần chính và tệp da khách hàng vào khung mẫu để tạo mô tả chuẩn."}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
