INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'f6a7b8c9-1012-4112-8112-6c7d8e9f0a12'::uuid, 'workflow-nhac-mua-lai-my-pham-zalo', 'Workflow Nhắc Lịch Mua Lại & CSKH Mỹ Phẩm Tự Động', 'Luồng n8n/Make nhắc chu kỳ hết sản phẩm sau 30–45 ngày qua Google Sheets, Telegram & mẫu Zalo.', 'Giải pháp tự động hóa giữ chân khách hàng dành riêng cho shop mỹ phẩm nhỏ không dùng CRM đắt tiền. Khi ghi nhận đơn dưỡng da vào Google Sheets, hệ thống tự tính ngày dự kiến dùng hết (30–45 ngày) và gửi thông báo nhắc nhân viên chăm sóc khách quay lại mua tiếp.', 'workflow', 'Mỹ phẩm', 640000, NULL, NULL, 'adapted', 'Chuyển thể từ cấu trúc luồng nhắc lịch mở trên n8n, Việt hóa và thiết kế lại bảng theo dõi chu kỳ dùng hết sản phẩm mỹ phẩm cho shop nhỏ.', '{"target_shop_size":"1-3 người","platforms":["Zalo","Google Sheets","Telegram"],"deliverables":["File JSON workflow n8n/Make nhập 1 chạm","Google Sheets mẫu quản lý chu kỳ mua lại 30–45 ngày","10 mẫu tin nhắn hỏi thăm dịu nhẹ đúng chính sách Zalo"],"tech_stack":["n8n / Make","Google Sheets","Telegram Bot"],"setup_time_minutes":40,"guide_summary":"Kết nối Google Sheets đơn hàng với bot Telegram để nhận danh sách khách cần nhắc chăm sóc mỗi sáng."}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  name = EXCLUDED.name,
