INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '3d6b22e3-11a4-4d88-9c21-2e3f4a5b6c7d'::uuid, 'template-lookbook-thoi-trang-local', 'Template Lookbook Thời Trang Shop Nhỏ', 'Giao diện trưng bày bộ sưu tập quần áo kèm bảng size trực quan và nút đặt hàng nhanh.', 'Thiết kế dành cho shop thời trang nữ/unisex bán trên Instagram, Facebook và Shopee. Hỗ trợ hiển thị ảnh lookbook theo mùa, bảng quy đổi size rõ ràng trên điện thoại và form giữ đơn nhanh cho khách xem live.', 'template', 'Thời trang', 590000, '/products/template-lookbook-thoi-trang-local', NULL, 'original', 'Mã nguồn thiết kế gốc bởi nhóm tác giả, hỗ trợ tùy biến màu sắc theo nhận diện shop.', '{"target_shop_size":"1-5 người","platforms":["Instagram","Facebook","Shopee"],"deliverables":["Template Lookbook + Bảng size responsive theo chiều cao cân nặng","Form giữ đơn nhanh gắn link Shopee/Instagram","Bộ banner kích thước chuẩn mạng xã hội"],"tech_stack":["HTML5","CSS3","TypeScript"],"setup_time_minutes":40,"guide_summary":"Cập nhật bộ ảnh lookbook theo mùa và thông số size S/M/L để khách tự đối chiếu trước khi đặt."}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
