INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'a1b2c3d4-1007-4107-8107-1c4f9b012a07'::uuid, 'template-landing-livestream-thoi-trang', 'Template Landing Page Flash Sale & Livestream Thời Trang', 'Trang gom đơn nhanh theo mã sản phẩm khi livestream TikTok/Facebook, tối ưu chọn màu & size trên di động.', 'Mẫu landing page chuyên dụng cho các shop thời trang bán qua phiên livestream hoặc xả kho cuối tuần. Hiển thị mã số sản phẩm theo thứ tự live, bộ đếm giữ giá ưu đãi, chọn nhanh biến thể màu/size và chuyển tiếp về giỏ hàng sàn hoặc inbox.', 'template', 'Thời trang', 550000, '/products/template-landing-livestream-thoi-trang', NULL, 'adapted', 'Chuyển thể từ khung layout bán hàng mở nội bộ, tối ưu lại luồng gom đơn theo mã live cho shop thời trang Việt Nam.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Facebook","Shopee"],"deliverables":["Trang danh sách mã live tìm kiếm tức thì theo mã #A01, #A02","Khối bộ đếm khung giờ Flash Sale & bảng chọn size/màu","Tài liệu hướng dẫn gắn link giỏ hàng trước giờ lên live"],"tech_stack":["HTML5","CSS3","Next.js"],"setup_time_minutes":30,"guide_summary":"Nhập danh sách mã hàng live vào file cấu hình JSON để ghim link trang gom đơn lên bình luận."}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
