INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'd4e5f6a7-1010-4110-8110-4a5b6c7d8e10'::uuid, 'prompt-pack-phoi-do-livestream-thoi-trang', 'Prompt Pack Phối Đồ, Tư Vấn Size & Kịch Bản Live Thời Trang', '55 prompt gợi ý mix-match theo dáng người, tư vấn size giảm hoàn hàng và kịch bản dẫn livestream 60s.', 'Bộ prompt dành cho chủ shop quần áo bận rộn bán trên Instagram, Facebook, TikTok Shop và Shopee. Hỗ trợ viết caption lookbook tự nhiên, trả lời nhanh câu hỏi chọn size theo số đo để hạn chế đổi trả, gợi ý phối thêm phụ kiện tăng giá trị đơn và soạn sườn nói chuyện khi live.', 'prompt_pack', 'Thời trang', 320000, NULL, NULL, 'original', 'Biên soạn gốc bởi nhóm nội dung, cấp quyền sử dụng lâu dài cho mọi kênh bán hàng của 1 thương hiệu thời trang.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Instagram","Facebook","Shopee"],"deliverables":["55 prompt chia 4 nhóm: Caption Lookbook, Tư vấn size, Mix-match, Kịch bản Live","Bảng mẫu phản hồi khách hỏi chất vải và chính sách đổi size","Checklist chuẩn bị nội dung trước phiên livestream 30 phút"],"tech_stack":["Notion","Markdown","PDF"],"setup_time_minutes":15,"guide_summary":"Chọn nhóm prompt tương ứng (đăng bài mới hoặc rep inbox chọn size) rồi điền thông số chất liệu, form dáng."}'::jsonb, true, false
