INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'b2c3d4e5-1008-4108-8108-2e3f4a5b6c08'::uuid, 'template-dat-combo-tiem-banh-fnb', 'Template Website Đặt Combo Tiệm Bánh & Quà Tặng F&B', 'Mẫu web đặt hộp bánh, set trà chiều có chọn khung giờ giao hẹn trước và nhập lời chúc trên thiệp.', 'Thiết kế tối ưu cho tiệm bánh thủ công, bếp đồ ăn vặt và cửa hàng set quà F&B bán theo đơn đặt trước (pre-order). Cho phép khách chọn combo vị bánh, khung giờ nhận trong ngày, nhập nội dung thiệp tặng và gửi xác nhận về Zalo/Messenger của tiệm.', 'template', 'F&B', 520000, '/products/template-dat-combo-tiem-banh-fnb', NULL, 'licensed', 'Sử dụng bộ UI kit và biểu tượng ẩm thực theo giấy phép thương mại mở rộng hợp lệ, luồng đặt combo và nội dung tiếng Việt do nhóm biên tập độc lập.', '{"target_shop_size":"1-4 người","platforms":["Zalo","Facebook","Instagram"],"deliverables":["Template trang đặt combo theo khung giờ giao nhận","Form ghi chú thiệp chúc & dị ứng nguyên liệu","Bộ ảnh khung trình bày hộp quà chuẩn tỷ lệ 4:3"],"tech_stack":["HTML5","CSS3","TypeScript"],"setup_time_minutes":35,"guide_summary":"Cài đặt khung giờ bếp giao hàng trong ngày và danh sách combo để khách đặt trước không bị trùng lịch."}'::jsonb, true, false
