INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'e5f6a7b8-1011-4111-8111-5b6c7d8e9f11'::uuid, 'prompt-pack-mo-ta-mon-fnb-review', 'Prompt Pack Mô Tả Món Ăn & Kịch Bản Video Review F&B', '50 prompt viết thực đơn hấp dẫn cho ShopeeFood/Zalo, kịch bản clip pha chế 20s và mẫu trả lời đánh giá.', 'Giúp chủ quán ăn, tiệm trà sữa, tiệm bánh online tự viết mô tả món ăn gợi vị giác chuẩn app giao đồ ăn, dựng video ngắn quay cảnh làm món tại quầy và phản hồi đánh giá 1–5 sao tinh tế để giữ điểm uy tín quán.', 'prompt_pack', 'F&B', 260000, NULL, NULL, 'original', 'Bộ prompt biên soạn gốc bởi nhóm nội dung, dùng không giới hạn cho các kênh bán hàng của 1 quán F&B.', '{"target_shop_size":"1-3 người","platforms":["ShopeeFood","TikTok","Zalo","Facebook"],"deliverables":["50 prompt viết mô tả món & combo tăng giá trị giỏ hàng","15 kịch bản video quay món/pha chế 20–30 giây","20 mẫu phản hồi đánh giá khách hàng (khen và góp ý)"],"tech_stack":["Notion","Markdown","PDF"],"setup_time_minutes":10,"guide_summary":"Nhập tên món, nguyên liệu đặc trưng và mức giá combo để tạo ngay mô tả chuẩn app giao đồ ăn."}'::jsonb, true, false
