INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  'c3d4e5f6-1009-4109-8109-3f4a5b6c7d09'::uuid, 'template-bio-link-cua-hang-mini-da-kenh', 'Template Trang Bio Link & Cửa Hàng Mini Đa Kênh', 'Trang tổng hợp link Shopee, TikTok Shop, Zalo OA và 8–12 sản phẩm chủ lực gắn trên bio mạng xã hội.', 'Phù hợp cho mọi chủ shop nhỏ bán cùng lúc nhiều kênh và cần một trang đích duy nhất gắn trên tiểu sử TikTok, Instagram, Facebook. Tải trang siêu nhẹ trên 4G, hiển thị mã giảm giá theo sàn và dẫn khách sang đúng kênh đặt mua quen thuộc.', 'template', 'Đa ngành', 390000, '/products/template-bio-link-cua-hang-mini-da-kenh', NULL, 'licensed', 'Sử dụng bộ icon và font cấp phép thương mại hợp lệ; cấu trúc trang Bio Link & cửa hàng mini được nhóm đóng gói chuẩn hóa cho shop Việt Nam.', '{"target_shop_size":"1-3 người","platforms":["TikTok Shop","Shopee","Zalo","Instagram"],"deliverables":["Trang Bio Link + Danh mục 12 sản phẩm chủ lực tối ưu di động","Nút điều hướng đa sàn kèm sao chép nhanh voucher","Hướng dẫn xuất bản miễn phí lên Vercel/Netlify trong 20 phút"],"tech_stack":["HTML5","CSS3","JavaScript"],"setup_time_minutes":20,"guide_summary":"Gắn URL gian hàng Shopee, TikTok Shop và Zalo OA vào file cấu hình rồi gắn link trang lên bio."}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug,
  name = EXCLUDED.name,
  short_description = EXCLUDED.short_description,
  description = EXCLUDED.description,
  product_type = EXCLUDED.product_type,
  industry = EXCLUDED.industry,
  price_vnd = EXCLUDED.price_vnd,
