INSERT INTO public.products (
  id, slug, name, short_description, description, product_type, industry, price_vnd, demo_url, thumbnail_url, source_type, license_note, specs, is_active, is_simulated
) VALUES (
  '6a9e55b6-44d7-40b1-cf54-5b6c7d8e9f01'::uuid, 'workflow-dong-bo-don-hang-google-sheet', 'Workflow Tự Động Ghi Đơn & Cảnh Báo Tồn Kho', 'Luồng tự động hóa đồng bộ đơn mới về Google Sheets và gửi thông báo Telegram/Zalo trong 1 phút.', 'Mẫu workflow n8n/Make đơn giản cho shop nhỏ không cần phần mềm ERP cồng kềnh. Tự động ghi nhận đơn hàng mới vào Google Sheets, tính doanh thu ngày và nhắn tin cảnh báo khi sản phẩm sắp hết hàng.', 'workflow', 'Đa ngành', 690000, NULL, NULL, 'original', 'Template workflow JSON do nhóm tự xây dựng, kèm hướng dẫn thiết lập từng bước.', '{"target_shop_size":"1-5 người","platforms":["Google Sheets","Telegram","Webhook"],"deliverables":["File JSON workflow nhập 1 chạm vào n8n/Make","Mẫu Google Sheets quản lý đơn hàng, doanh thu ngày & tồn kho","Tài liệu nối Webhook và cài đặt cảnh báo hết hàng qua Telegram"],"tech_stack":["n8n / Make","Google Sheets","Telegram Bot"],"setup_time_minutes":45,"guide_summary":"Import file JSON vào n8n/Make, chọn Google Sheets mẫu và dán Bot Token Telegram để chạy tự động."}'::jsonb, true, false
) ON CONFLICT (id) DO UPDATE SET
