-- 4. Experiment Scenarios (SC-01..SC-04)
INSERT INTO public.scenarios (
  id, code, title, prompt_text, industry, budget_vnd, difficulty, expected_product_id, acceptable_product_ids, rubric_note, sort_order, is_active
) VALUES (
  '9f1e2d3c-4b5a-4678-8901-abcdef123456'::uuid, 'SC-01', 'Kịch bản 1: Shop mỹ phẩm dưỡng da trên TikTok Shop', 'Bạn đang vận hành shop mỹ phẩm 2 người trên TikTok Shop, ngân sách dưới 1.000.000đ. Hãy chọn gói sản phẩm phù hợp nhất để làm trang bán hàng tối ưu màn hình điện thoại 375px, trình bày bảng thành phần dịu nhẹ và tuân thủ chính sách quảng cáo không cam kết trị liệu.', 'Mỹ phẩm', 1000000, 'medium', '2c5a98b1-90c4-4f88-a2b3-1c4f9b012a10'::uuid, ARRAY['7a9c11d2-54e3-4c99-8b10-0f2d3e4a5b6c'::uuid]::uuid[], 'Đáp án ưu tiên nhất là Template Landing Page Mỹ Phẩm Chuẩn TikTok Shop (490.000đ) vì giải quyết trực tiếp nhu cầu trang bán hàng 375px & bảng thành phần; chấp nhận Prompt Pack Mô Tả & Kịch Bản Video Mỹ Phẩm (290.000đ) nếu người tham gia ưu tiên nội dung tuân thủ chính sách không trị liệu.', 1, true
) ON CONFLICT (id) DO UPDATE SET
  code = EXCLUDED.code,
  title = EXCLUDED.title,
  prompt_text = EXCLUDED.prompt_text,
  industry = EXCLUDED.industry,
  budget_vnd = EXCLUDED.budget_vnd,
  difficulty = EXCLUDED.difficulty,
  expected_product_id = EXCLUDED.expected_product_id,
  acceptable_product_ids = EXCLUDED.acceptable_product_ids,
  rubric_note = EXCLUDED.rubric_note,
  sort_order = EXCLUDED.sort_order,
  is_active = EXCLUDED.is_active;

INSERT INTO public.scenarios (
  id, code, title, prompt_text, industry, budget_vnd, difficulty, expected_product_id, acceptable_product_ids, rubric_note, sort_order, is_active
) VALUES (
  '8e2d3c4b-5a6b-4789-9012-bcdef1234567'::uuid, 'SC-02', 'Kịch bản 2: Shop thời trang cần trang Lookbook & bảng size', 'Bạn quản lý shop thời trang local 2 người, ngân sách tối đa 700.000đ. Bạn cần một trang trưng bày bộ sưu tập lookbook kèm bảng quy đổi size trực quan cho khách xem livestream từ Instagram và Shopee cùng form giữ đơn nhanh.', 'Thời trang', 700000, 'medium', '3d6b22e3-11a4-4d88-9c21-2e3f4a5b6c7d'::uuid, ARRAY['a1b2c3d4-1007-4107-8107-1c4f9b012a07'::uuid]::uuid[], 'Đáp án chuẩn là Template Lookbook Thời Trang Shop Nhỏ (590.000đ) vì có đủ gallery bộ sưu tập và bảng quy đổi size trực quan; chấp nhận Template Landing Page Flash Sale & Livestream Thời Trang (550.000đ) vì cùng nằm dưới trần 700.000đ và có chức năng giữ đơn livestream.', 2, true
) ON CONFLICT (id) DO UPDATE SET
  code = EXCLUDED.code,
  title = EXCLUDED.title,
  prompt_text = EXCLUDED.prompt_text,
  industry = EXCLUDED.industry,
  budget_vnd = EXCLUDED.budget_vnd,
  difficulty = EXCLUDED.difficulty,
  expected_product_id = EXCLUDED.expected_product_id,
  acceptable_product_ids = EXCLUDED.acceptable_product_ids,
